<?php
require_once __DIR__ . '/../config.php';
requireAuth();
$pageTitle = 'Gold Give Details';
$id = (int) query('id', 0); $db = getDB();
$stmt = $db->prepare("SELECT g.*, c.name as customer_name, c.phone as customer_phone FROM gold_gives g LEFT JOIN customers c ON c.id=g.customer_id WHERE g.id=? AND g.deleted_at IS NULL"); $stmt->execute([$id]); $give=$stmt->fetch();
if(!$give){ setFlash('error','Gold give not found.'); redirect('gold-gives/index.php'); }
$stmt=$db->prepare("SELECT * FROM gold_give_items WHERE give_id=?"); $stmt->execute([$id]); $items=$stmt->fetchAll();
require_once __DIR__ . '/../includes/header.php';
?>
