<div class="invoice-detail-grid"><div class="detail-card"><h3>Give Information</h3><div class="detail-row"><span class="detail-label">Give No</span><span class="detail-value"><?= htmlspecialchars($give['give_no']) ?></span></div><div class="detail-row"><span class="detail-label">Date</span><span class="detail-value"><?= formatDate($give['give_date']) ?></span></div><div class="detail-row"><span class="detail-label">Type</span><span class="detail-value"><span class="badge bg-info"><?= ucfirst($give['give_type']) ?></span></span></div><?php if($give['remarks']): ?><div class="detail-row"><span class="detail-label">Remarks</span><span class="detail-value"><?= htmlspecialchars($give['remarks']) ?></span></div><?php endif; ?></div><div class="detail-card"><h3>Party</h3><div class="detail-row"><span class="detail-label">Name</span><span class="detail-value"><a href="<?= url('customers/show.php?id='.$give['customer_id']) ?>" style="color:var(--gold-primary);"><?= htmlspecialchars($give['customer_name'] ?? 'N/A') ?></a></span></div><div class="detail-row"><span class="detail-label">Phone</span><span class="detail-value"><?= htmlspecialchars($give['customer_phone'] ?? '-') ?></span></div></div></div>
<div class="card" style="padding:24px;margin-top:24px;"><h3 style="font-family:'Playfair Display',serif;margin-bottom:16px;color:var(--gold-primary);">Items Given</h3><div class="table-container"><table><thead><tr><th>Description</th><th class="text-right">Gross Weight (g)</th><th class="text-right">Ratti Impurity</th><th class="text-right">Khalis Given (g)</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><?= htmlspecialchars($item['description'] ?: '-') ?></td><td class="text-right mono"><?= number_format($item['gross_weight'],3) ?></td><td class="text-right mono"><?= number_format($item['ratti_impurity'],3) ?></td><td class="text-right mono text-danger" style="font-weight:600;"><?= number_format($item['khalis_weight'],3) ?></td></tr><?php endforeach; ?></tbody><tfoot><tr style="font-weight:700;background:var(--bg-surface);"><td>Total</td><td class="text-right mono"><?= number_format($give['total_gross_weight'],3) ?></td><td></td><td class="text-right mono text-danger"><?= number_format($give['total_khalis_weight'],3) ?></td></tr></tfoot></table></div></div>
